<?php
header('Content-Type: application/json; charset=utf-8');date_default_timezone_set('Asia/Jakarta');require_once __DIR__.'/../Config/database.php';
try{$pdo=(new Database())->connect();$pdo->exec("SET time_zone = '+07:00'");$allowed=['10m'=>10,'1h'=>60,'6h'=>360,'24h'=>1440];$range=strtolower($_GET['range']??'10m');if(!isset($allowed[$range]))$range='10m';$minutes=$allowed[$range];$limit=$range==='24h'?500:($range==='6h'?360:($range==='1h'?180:120));$rid=(int)($_GET['router_id']??0);if($rid<=0){$q=$pdo->query("SELECT id,router_name FROM router ORDER BY is_active DESC,CASE WHEN status='ONLINE' THEN 0 ELSE 1 END,id ASC LIMIT 1");$rr=$q->fetch(PDO::FETCH_ASSOC)?:[];$rid=(int)($rr['id']??0);$routerName=$rr['router_name']??null;}else{$q=$pdo->prepare('SELECT router_name FROM router WHERE id=? LIMIT 1');$q->execute([$rid]);$routerName=$q->fetchColumn()?:null;}$where='interface_name = :iface AND created_at >= DATE_SUB(NOW(), INTERVAL :minutes MINUTE) AND created_at <= NOW()';$params=[':iface'=>'ether1',':minutes'=>$minutes];if($rid>0){$where.=' AND router_id = :router_id';$params[':router_id']=$rid;}$rangeStmt=$pdo->prepare('SELECT DATE_SUB(NOW(), INTERVAL :m MINUTE) range_from,NOW() range_to');$rangeStmt->bindValue(':m',$minutes,PDO::PARAM_INT);$rangeStmt->execute();$ri=$rangeStmt->fetch(PDO::FETCH_ASSOC)?:[];$from=$ri['range_from']??null;$to=$ri['range_to']??null;$stmt=$pdo->prepare("SELECT created_at,download_mbps,upload_mbps FROM traffic_history WHERE $where ORDER BY created_at DESC LIMIT $limit");foreach($params as $k=>$v)$stmt->bindValue($k,$v,is_int($v)?PDO::PARAM_INT:PDO::PARAM_STR);$stmt->execute();$rows=array_reverse($stmt->fetchAll(PDO::FETCH_ASSOC));$statsStmt=$pdo->prepare("SELECT COALESCE(MAX(download_mbps),0) peak_download,COALESCE(MAX(upload_mbps),0) peak_upload,COALESCE(AVG(download_mbps),0) avg_download,COALESCE(AVG(upload_mbps),0) avg_upload,COUNT(*) records FROM traffic_history WHERE $where");foreach($params as $k=>$v)$statsStmt->bindValue($k,$v,is_int($v)?PDO::PARAM_INT:PDO::PARAM_STR);$statsStmt->execute();$stats=$statsStmt->fetch(PDO::FETCH_ASSOC)?:[];$latestStmt=$pdo->prepare("SELECT created_at FROM traffic_history WHERE interface_name='ether1'".($rid>0?' AND router_id=:router_id':'').' ORDER BY created_at DESC LIMIT 1');if($rid>0)$latestStmt->bindValue(':router_id',$rid,PDO::PARAM_INT);$latestStmt->execute();$latest=$latestStmt->fetchColumn();$latestTimestamp=$latest?strtotime($latest):null;$age=$latestTimestamp!==false&&$latestTimestamp!==null?max(0,time()-$latestTimestamp):null;$status=$age===null?'OFFLINE':($age<=30?'HEALTHY':($age<=60?'DELAYED':'OFFLINE'));$labels=[];$downloads=[];$uploads=[];foreach($rows as $row){$ts=strtotime($row['created_at']??'');$labels[]=$ts!==false?date('H:i:s',$ts):($row['created_at']??'');$downloads[]=(float)($row['download_mbps']??0);$uploads[]=(float)($row['upload_mbps']??0);}echo json_encode(['success'=>true,'router_id'=>$rid,'router_name'=>$routerName,'range'=>$range,'from'=>$from,'to'=>$to,'labels'=>$labels,'downloads'=>$downloads,'uploads'=>$uploads,'peak_download'=>(float)($stats['peak_download']??0),'peak_upload'=>(float)($stats['peak_upload']??0),'avg_download'=>(float)($stats['avg_download']??0),'avg_upload'=>(float)($stats['avg_upload']??0),'records'=>(int)($stats['records']??0),'points'=>count($rows),'latest_sample'=>$latest,'collector_age'=>$age,'collector_status'=>$status],JSON_UNESCAPED_UNICODE);}catch(Throwable $e){http_response_code(500);echo json_encode(['success'=>false,'message'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
